document.addEventListener('DOMContentLoaded', () => {
  const app = document.getElementById('app');
  if (!app) return;
  
  const theme = DECK_INFO.config.themeColor;
  const bg = DECK_INFO.config.backgroundColor;
  const lang = DECK_INFO.config.defaultLanguage;

  app.innerHTML = `
    <div id="reader-ui" style="min-height: 100vh; display: flex; flex-direction: column; align-items: center; justify-content: center; background: ${bg}; color: #fff; font-family: 'Inter', sans-serif; text-align: center; padding: 2rem;">
      <h1 style="font-family: 'Cinzel', serif; color: ${theme}; font-size: 2.5rem; margin-bottom: 0.5rem; letter-spacing: 0.1em;">${DECK_INFO.config.appName}</h1>
      <p style="opacity: 0.5; text-transform: uppercase; letter-spacing: 0.3em; font-size: 0.7rem; margin-bottom: 4rem;">Living Oracle Reader</p>
      
      <div id="draw-container" style="perspective: 1000px; cursor: pointer;" onclick="drawCard()">
        <div id="card-inner" style="position: relative; width: 220px; height: 350px; transition: transform 0.8s; transform-style: preserve-3d; margin: 0 auto;">
          <div style="position: absolute; width: 100%; height: 100%; backface-visibility: hidden; border-radius: 1.5rem; overflow: hidden; box-shadow: 0 20px 50px rgba(0,0,0,0.5);">
            <img src="${DECK_INFO.backImage}" style="width: 100%; height: 100%; object-fit: cover;">
          </div>
          <div id="card-front" style="position: absolute; width: 100%; height: 100%; backface-visibility: hidden; transform: rotateY(180deg); border-radius: 1.5rem; overflow: hidden; box-shadow: 0 20px 50px rgba(0,0,0,0.5);">
            <img id="drawn-img" src="" style="width: 100%; height: 100%; object-fit: cover;">
          </div>
        </div>
      </div>

      <div id="meaning-panel" style="margin-top: 3rem; max-width: 500px; opacity: 0; transition: 1s;">
        <h2 id="card-title" style="font-family: 'Cinzel', serif; color: ${theme}; font-size: 1.8rem; margin: 0;"></h2>
        <p id="card-desc" style="line-height: 1.8; color: #ccc; margin-top: 1rem;"></p>
        <button onclick="resetReader()" style="margin-top: 2rem; background: none; border: 1px solid rgba(255,255,255,0.2); color: #666; padding: 0.8rem 2rem; border-radius: 2rem; cursor: pointer; text-transform: uppercase; font-size: 0.7rem; font-weight: 900; letter-spacing: 0.1em;">Reset Ritual</button>
      </div>

      <p id="prompt-text" style="margin-top: 2rem; opacity: 0.3; font-size: 0.8rem; font-weight: 600;">TAP THE DECK TO INVOKE</p>
    </div>
  `;

  window.drawCard = () => {
    const cardIdx = Math.floor(Math.random() * DECK_INFO.cards.length);
    const card = DECK_INFO.cards[cardIdx];
    
    document.getElementById('drawn-img').src = card.image;
    document.getElementById('card-inner').style.transform = 'rotateY(180deg)';
    document.getElementById('meaning-panel').style.opacity = '1';
    document.getElementById('prompt-text').style.opacity = '0';
    document.getElementById('card-title').innerText = card.title[lang];
    document.getElementById('card-desc').innerText = card.meaning[lang];
    document.getElementById('draw-container').onclick = null;
  };

  window.resetReader = () => {
    document.getElementById('card-inner').style.transform = 'rotateY(0deg)';
    document.getElementById('meaning-panel').style.opacity = '0';
    document.getElementById('prompt-text').style.opacity = '0.3';
    setTimeout(() => {
      document.getElementById('draw-container').onclick = drawCard;
    }, 800);
  };
});